// The renderer's data for the Node build tools (build_we_scene.mjs), like src/asset_source.js in the browser:
//   'extracted'   your extracted firmware files (extracted_lines/, assets/): the exact originals
//   'procedural'  generated by src/procedural.js: no firmware files needed or embedded
//   'auto'        extracted when extracted_lines/ is present, procedural otherwise
import { readFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { inflateSync } from 'node:zlib';
import { parseMnu, mergeMnu } from '../src/spline_engine.js';
import * as P from '../src/procedural.js';

const ROOT = join(import.meta.dirname, '..', '..');

// PNG (8-bit RGB / RGBA, non-interlaced) -> RGBA8 Buffer, row 0 = top
export function decodePng(path, size = null) {
  const b = readFileSync(path);
  let p = 8, W = 0, H = 0, ct = 0;
  const idat = [];
  while (p < b.length) {
    const l = b.readUInt32BE(p), t = b.toString('ascii', p + 4, p + 8);
    if (t === 'IHDR') { W = b.readUInt32BE(p + 8); H = b.readUInt32BE(p + 12); ct = b[p + 17]; }
    if (t === 'IDAT') idat.push(b.subarray(p + 8, p + 8 + l));
    p += 12 + l;
  }
  const bpp = ct === 6 ? 4 : 3, raw = inflateSync(Buffer.concat(idat)), st = W * bpp + 1, px = Buffer.alloc(W * H * bpp);
  for (let y = 0; y < H; y++) {
    const f = raw[y * st];
    for (let x = 0; x < W * bpp; x++) {
      const a = x >= bpp ? px[y * W * bpp + x - bpp] : 0, up = y ? px[(y - 1) * W * bpp + x] : 0, c = x >= bpp && y ? px[(y - 1) * W * bpp + x - bpp] : 0;
      let v = raw[y * st + 1 + x];
      if (f === 1) v += a; else if (f === 2) v += up; else if (f === 3) v += (a + up) >> 1;
      else if (f === 4) { const pp = a + up - c, pa = Math.abs(pp - a), pb = Math.abs(pp - up), pc = Math.abs(pp - c); v += pa <= pb && pa <= pc ? a : pb <= pc ? up : c; }
      px[y * W * bpp + x] = v & 255;
    }
  }
  if (size && (W !== size[0] || H !== size[1])) throw new Error(`${path}: expected ${size[0]}x${size[1]}`);
  const rgba = Buffer.alloc(W * H * 4);
  for (let i = 0; i < W * H; i++) { for (let k = 0; k < 3; k++) rgba[i * 4 + k] = px[i * bpp + k]; rgba[i * 4 + 3] = bpp === 4 ? px[i * bpp + 3] : 255; }
  return rgba;
}

export function nodeAssets(mode = 'auto') {
  if (mode === 'auto') mode = existsSync(join(ROOT, 'extracted_lines', 'BACKGROUND.mnu')) ? 'extracted' : 'procedural';
  if (mode === 'procedural') {
    const t = P.splineTables();
    return {
      mode,
      mnu: (file, preset) => P.presetMnu(file, preset),
      month: (m, kind) => Buffer.from(P.month(m, kind)),             // m = 0..11; 64 x 32 RGBA8
      iridescent: () => Buffer.from(P.iridescent(128)),              // 128 x 128 RGBA8
      fresLut: () => Buffer.from(P.fresLut()),                       // 512 x 1 RGBA8
      splineFloats: () => [...t.B, ...t.D, ...t.basis.flat()],      // the layout of assets/tables/spline_tables.bin
      snapshotFloats: () => { const s = P.snapshot(); return [...s.pos, ...s.vel]; },
    };
  }
  const floats = (p) => { const b = readFileSync(join(ROOT, p)); return Array.from(new Float32Array(b.buffer, b.byteOffset, b.length / 4)); };
  const readMnu = (p) => parseMnu(readFileSync(p, 'latin1'));
  const pad = (i) => String(i).padStart(2, '0');
  return {
    mode,
    mnu: (file, preset) => mergeMnu(readMnu(join(ROOT, 'extracted_lines', `${file}.mnu`)),
      (() => { try { return readMnu(join(ROOT, 'extracted_lines', 'override', preset, `${file}.mnu`)); } catch { return {}; } })()),
    month: (m, kind) => decodePng(join(ROOT, 'assets', 'png', `month_${kind}_${pad(m + 1)}.png`), [64, 32]),
    iridescent: () => decodePng(join(ROOT, 'assets', 'png', 'proc_iridescent.png'), [128, 128]),
    fresLut: () => readFileSync(join(ROOT, 'assets', 'lines', 'freslut_512x1.bin')),
    splineFloats: () => floats('assets/tables/spline_tables.bin'),
    snapshotFloats: () => { const s = P.snapshot(); return [...s.pos, ...s.vel]; },   // always the generated start
  };
}
